/* ============================================================
   thaisound4.js — เสียงเครื่องดนตรีชุดที่ 4 · วงกลองปู่เจ่และกลองสะบัดชัยของชมรม (อัดจริง 3 พ.ย. 2569)
   กลองปู่เจ่ (ตีด้วยมือ 3 เสียง) · ฉาบ (เปิด–ปิด) · ฆ้องราว · กลองสะบัดชัย (หน้ากลอง–ขอบ)
   ตัดจากคลิปที่ครูถ่ายไว้ เลือกเฉพาะลูกที่ตีเดี่ยวไม่ทับกัน ลดเสียงห้อง/เสียงพัดลมด้วยการลบสเปกตรัมพื้น
   ระดับเสียงที่วัดได้: กลองปู่เจ่ 106 / 204 / 367 Hz · ฆ้องราวลูกใหญ่ 259 Hz · กลองสะบัดชัย 175 Hz (ขอบ 793 Hz)
   หมายเหตุ: ฆ้องราวมี 4 ลูก แต่คลิปมีเฉพาะลูกใหญ่ ลูกที่ 2–4 จึงปรับระดับเสียงขึ้นจากลูกใหญ่ไว้ก่อน
             ถ้าอัดลูกที่เหลือมาเพิ่ม ให้ใส่ไฟล์เสียงแทนแล้วแก้ KHONGF ให้ตรงของจริง
   ใช้: TS4.init(audioContext, outputNode) แล้วเรียก
     TS4.pujae(k,t,v,out)     กลองปู่เจ่ k 0 เสียงเปิดกลางหน้า (ตุ้ม) · 1 เสียงกลาง (ป๊ะ) · 2 เสียงขอบสูง (แต๊ะ)
     TS4.chab(k,t,v,out)      ฉาบวงกลองปู่เจ่ k 0 เปิด (ฉาบ) · 1 ปิด (ฉับ)
     TS4.khongrao(k,t,v,out)  ฆ้องราว k 0 ลูกใหญ่สุด … 3 ลูกเล็กสุด
     TS4.khongF(f,t,v,out)    ฆ้องราวที่ความถี่ f
     TS4.sabat(k,t,v,out)     กลองสะบัดชัย k 0 ตีกลางหน้ากลอง · 1 ตีขอบ/ไม้
     TS4.ready(k)             พร้อมเล่นหรือยัง
   พัฒนาโดย นายนนทพัทธ์ วงค์มูล 2026
   ============================================================ */
(function(){
  'use strict';
  const SRC={"pj_lo": "data:audio/mpeg;base64,", "pj_mid": "data:audio/mpeg;base64,", "pj_hi": "data:audio/mpeg;base64,", "cb_open": "data:audio/mpeg;base64,", "cb_shut": "data:audio/mpeg;base64,", "kr_big": "data:audio/mpeg;base64,", "sb_hit": "data:audio/mpeg;base64,", "sb_rim": "data:audio/mpeg;base64,"};
  const KHONGF=[259,345,435,518];      /* ลูกใหญ่ 259 Hz เป็นเสียงจริง · ลูกอื่นปรับขึ้นจากลูกใหญ่ */
  let AC=null,OUT=null;const B={};
  function init(ac,out){if(AC===ac)return;AC=ac;OUT=out||ac.destination;
    Object.keys(SRC).forEach(k=>{fetch(SRC[k]).then(r=>r.arrayBuffer()).then(ab=>new Promise((res,rej)=>AC.decodeAudioData(ab,res,rej))).then(b=>{
      const d=b.getChannelData(0);let m=0;for(let i=0;i<d.length;i++)m=Math.max(m,Math.abs(d[i]));let s=0;while(s<d.length&&Math.abs(d[s])<m*.05)s++;
      B[k]={b,off:Math.max(0,s/b.sampleRate-.003)}}).catch(()=>{})})}
  const ready=k=>!!(k?B[k]:Object.keys(SRC).every(x=>B[x]));
  function play(key,t,v,rate,out,dur){const s=B[key];if(!AC||!s)return false;t=Math.max(t||0,AC.currentTime);rate=rate||1;
    const n=AC.createBufferSource(),g=AC.createGain();n.buffer=s.b;n.playbackRate.value=rate;g.gain.setValueAtTime(v==null?1:v,t);
    if(dur){g.gain.setValueAtTime(v==null?1:v,t+Math.max(.03,dur-.06));g.gain.linearRampToValueAtTime(0,t+dur)}
    n.connect(g);g.connect(out||OUT);n.start(t,s.off);if(dur)n.stop(t+dur+.05);return true}
  const cl=(k,n)=>Math.max(0,Math.min(n,k|0));
  window.TS4={init,ready,KHONGF,
    pujae:(k,t,v,out)=>play(['pj_lo','pj_mid','pj_hi'][cl(k,2)],t,v,1,out),
    chab:(k,t,v,out)=>play(k?'cb_shut':'cb_open',t,v,1,out),
    khongrao:(k,t,v,out)=>play('kr_big',t,v,KHONGF[cl(k,3)]/KHONGF[0],out),
    khongF:(f,t,v,out)=>play('kr_big',t,v,Math.max(.4,Math.min(3,(f||259)/KHONGF[0])),out),
    sabat:(k,t,v,out)=>play(k?'sb_rim':'sb_hit',t,v,1,out),
    /* เล่นแบบกำหนดความยาว (ใช้ตอนต้องการหยุดเสียงก้องก่อนจบ เช่น ตีรัว) */
    cut:(name,t,v,dur,out)=>play(name,t,v,1,out,dur)};
})();
